---@param msg  SC_RetStarts
function RaceXCupManager:BeginBattle(msg,isReplay)
    self.roomId=0
    self.IsReplay=isReplay
    self.Queue = Queue()
    self.BattleResult={}
    if msg.starts and #msg.starts>=1 then
        self.BattleCount=#msg.starts
        for i = 1, #msg.starts do
            local temp={}
            temp.value=msg.starts[i]
            temp.idx=i
            self.Queue:EnQueueFront(temp)
        end
    else
        self.BattleCount=1
        local temp={}
        temp.value=msg
        temp.idx=1
        self.Queue:EnQueueFront(temp)
    end

    self:FightBattle()
end
function RaceXCupManager:FightBattle()
    if self.Queue:GetSize()>0 then
        local value= self.Queue:DeQueueBack().value
        self.CurBattle=value
        BattleDataManager:Get():SetRoomData(value, RaceModel.RaceXcp,self.isReplay)
        local scenename = BattleDataManager:Get():GetSceneName()
        local trackdata = BattleDataManager:Get():GetTrackData()
        SceneManager:Get():LoadingBattleScene(scenename, trackdata, RaceModel.RaceXcp)
    end
end

function RaceXCupManager:BattleFinish()
    if self.Queue:GetSize()>0 then
        BattleDataManager:Get():SetStateBattleExit()
        self:FightBattle()
    else
        SceneManager:Get():LoadingMainCity(LoadingMainCityType.BattleToJcp)
        BattleDataManager:Get():SetStateBattleExit()
        self.RaceType=nil
    end
end
---@param result BattleResultData
function RaceXCupManager:AddBattleResult(time,rank,error,sign)
    local temp={}
    temp.time=time
    temp.rank=rank
    temp.error=error
    temp.sign=sign
    table.insert(self.BattleResult,temp)
    self.lastFlag=RaceXCupManager:Get().Queue:GetSize()==0
    if self.lastFlag or error~=BattleFailError.None then
        local caridx=""
        local time=""
        local error=""
        local rank=""
        local sign=""
        for i = 1, self.BattleCount do
            local temp=self.BattleResult[i]
            if i<self.BattleCount then
                if temp then
                    --caridx=caridx..temp.carid..":"
                    time=time..temp.time..":"
                    error=error..temp.error..":"
                    rank=rank..temp.rank..":"
                    sign=sign..temp.sign
                else
                    -- caridx=caridx..temp.carid..":"
                    time=time.. 0 ..":"
                    error=error.. -1 ..":"
                    rank=rank.. -1 ..":"
                    sign=sign.. -1 ..":"
                end
            else
                if temp then
                    --caridx=caridx..temp.carid
                    time=time..temp.time
                    error=error..temp.error
                    rank=rank..temp.rank
                    sign=sign..temp.sign
                else
                    -- caridx=caridx..temp.carid
                    time=time.. 0
                    error=error.. -1
                    rank=rank.. -1
                    sign=sign.. -1
                end
            end

        end
        RaceXCupManager:Get().Queue:Clear()
        RaceXCupSubsystem:Get():SendMsg_Finish(time,rank,error,self.roomId,sign)
        self.RaceType=nil
    else
        BattleDataManager:Get():SetStateBattleResult()
    end
end
function RaceXCupManager:FinishBattle(time,rank,error,sign)
    if self:GetRaceType()==RaceJcpRaceType.Test then
        if error~=BattleFailError.None then
            RaceXCupManager:Get().Queue:Clear()
        end
        self:SetStateBattleResult()
    elseif self:GetRaceType()==RaceJcpRaceType.Battle then
        self:AddBattleResult(time,rank,error,sign)
    elseif self:GetRaceType()==RaceJcpRaceType.Record then
        self:SetStateBattleResult()
    end
end

function RaceXCupManager:SetStateBattleResult()
    BattleDataManager:Get():SetStateBattleResult()
end